async fn bump_series_version(
    transaction: &mut sqlx::Transaction<'_, sqlx::Sqlite>,
    calendar_id: i64,
    series_id: i64,
    expected_version: i64,
    actor_user_id: i64,
    now: i64,
) -> Result<(), EventServiceError> {
    let updated = sqlx::query(
        "UPDATE events
         SET version = version + 1, last_edited_by_user_id = ?, updated_at = ?
         WHERE calendar_id = ? AND id = ? AND recurrence_rule IS NOT NULL AND version = ?",
    )
    .bind(actor_user_id)
    .bind(now)
    .bind(calendar_id)
    .bind(series_id)
    .bind(expected_version)
    .execute(&mut **transaction)
    .await?;
    if updated.rows_affected() == 1 {
        return Ok(());
    }
    let current_version: Option<i64> = sqlx::query_scalar(
        "SELECT version FROM events
         WHERE calendar_id = ? AND id = ? AND recurrence_rule IS NOT NULL",
    )
    .bind(calendar_id)
    .bind(series_id)
    .fetch_optional(&mut **transaction)
    .await?;
    match current_version {
        Some(current_version) => Err(EventServiceError::Conflict { current_version }),
        None => Err(EventServiceError::NotFound),
    }
}

async fn insert_event_audit(
    transaction: &mut sqlx::Transaction<'_, sqlx::Sqlite>,
    actor_user_id: i64,
    action: &'static str,
    event_id: i64,
    now: i64,
) -> Result<(), sqlx::Error> {
    sqlx::query(
        "INSERT INTO audit_log (
            actor_user_id, action, target_type, target_id, metadata_json, created_at
         ) VALUES (?, ?, 'event', ?, NULL, ?)",
    )
    .bind(actor_user_id)
    .bind(action)
    .bind(event_id.to_string())
    .bind(now)
    .execute(&mut **transaction)
    .await?;
    Ok(())
}

/// Record one CalDAV change-log entry inside the caller's transaction.
///
/// This is the single, centralized point where base event mutations are
/// recorded for CalDAV sync. Because the insert shares the caller's
/// transaction, a committed mutation leaves exactly one row and a rolled-back
/// mutation leaves none. DAV-originated mutations flow through the same
/// domain-service methods, so they are recorded exactly once and never
/// double-counted by the DAV layer.
///
/// `resource_name` is carried for deleted changes so sync-collection (T11) can
/// emit the correct href after the tombstone has cleared the live mapping's
/// event reference. It is `None` for created/updated changes, where the name
/// is resolved from the live mapping at read time.
async fn record_caldav_change(
    transaction: &mut sqlx::Transaction<'_, sqlx::Sqlite>,
    calendar_id: i64,
    event_id: i64,
    change_type: &'static str,
    now: i64,
    resource_name: Option<&str>,
) -> Result<(), sqlx::Error> {
    sqlx::query(
        "INSERT INTO caldav_event_changes (
            calendar_id, event_id, change_type, created_at, resource_name
         ) VALUES (?, ?, ?, ?, ?)",
    )
    .bind(calendar_id)
    .bind(event_id)
    .bind(change_type)
    .bind(now)
    .bind(resource_name)
    .execute(&mut **transaction)
    .await?;
    Ok(())
}

/// Tombstone the live DAV mapping for an event, if any, inside the caller's
/// transaction. Clearing the event reference before the event row is removed
/// keeps the mapping's foreign key satisfied and leaves a durable tombstone
/// for other clients, matching the DAV delete path (T09).
async fn tombstone_caldav_mapping(
    transaction: &mut sqlx::Transaction<'_, sqlx::Sqlite>,
    calendar_id: i64,
    event_id: i64,
    now: i64,
) -> Result<(), sqlx::Error> {
    sqlx::query(
        "UPDATE caldav_event_resources
             SET event_id = NULL, deleted_at = ?, updated_at = ?
           WHERE calendar_id = ? AND event_id = ? AND deleted_at IS NULL",
    )
    .bind(now)
    .bind(now)
    .bind(calendar_id)
    .bind(event_id)
    .execute(&mut **transaction)
    .await?;
    Ok(())
}

fn validate_mutation(event: &EventMutation) -> Result<(), EventServiceError> {
    if event.title.trim().is_empty() {
        return Err(EventServiceError::InvalidInput);
    }
    validate_timing(&event.timing).map_err(|_| EventServiceError::InvalidInput)
}

#[derive(Clone, Debug)]
pub struct EventMutation {
    pub title: String,
    pub description: Option<String>,
    pub location: Option<String>,
    pub status: EventStatus,
    pub timing: EventTiming,
}

#[derive(Clone, Debug)]
pub struct EventChange {
    pub expected_version: i64,
    pub target_calendar_id: i64,
    pub event: EventMutation,
}

#[derive(Clone, Debug)]
pub struct OccurrenceChange {
    pub recurrence_id: i64,
    pub expected_version: i64,
    pub event: EventMutation,
}

#[derive(Clone, Debug)]
pub struct AllDayOccurrenceChange {
    pub recurrence_date: String,
    pub expected_version: i64,
    pub event: EventMutation,
}

#[derive(Clone, Copy)]
enum EventAccess {
    Details,
    FreeBusy,
}

#[derive(Clone, Debug, Serialize)]
pub struct EventProjection {
    pub id: i64,
    pub calendar_id: i64,
    pub access: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub location: Option<String>,
    pub status: &'static str,
    pub event_kind: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub start_utc: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub end_utc: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub timezone: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub start_date: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub end_date: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub created_by_user_id: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub last_edited_by_user_id: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub version: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub created_at: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub updated_at: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub recurrence_rule: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub series_id: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub recurrence_id: Option<i64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub recurrence_date: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub is_external: Option<bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub read_only: Option<bool>,
}

async fn mark_external_projections(
    pool: &SqlitePool,
    projections: &mut [EventProjection],
) -> Result<(), EventServiceError> {
    for projection in projections {
        let is_external = sqlx::query_scalar::<_, bool>(
            "SELECT EXISTS(SELECT 1 FROM external_event_mapping WHERE event_id = ?)",
        )
        .bind(projection.id)
        .fetch_one(pool)
        .await?;
        if is_external {
            projection.is_external = Some(true);
            projection.read_only = Some(true);
        }
    }
    Ok(())
}

fn project_event(event: Event, access: EventAccess) -> EventProjection {
    let details = matches!(access, EventAccess::Details);
    let (event_kind, start_utc, end_utc, timezone, start_date, end_date) = match event.timing {
        EventTiming::Timed {
            start_utc,
            end_utc,
            timezone,
        } => (
            "timed",
            Some(start_utc),
            Some(end_utc),
            details.then_some(timezone),
            None,
            None,
        ),
        EventTiming::AllDay {
            start_date,
            end_date,
        } => (
            "all_day",
            None,
            None,
            None,
            Some(start_date),
            Some(end_date),
        ),
    };
    EventProjection {
        id: event.id,
        calendar_id: event.calendar_id,
        access: if details { "details" } else { "free_busy" },
        title: details.then_some(event.title),
        description: if details { event.description } else { None },
        location: if details { event.location } else { None },
        status: event.status.as_str(),
        event_kind,
        start_utc,
        end_utc,
        timezone,
        start_date,
        end_date,
        created_by_user_id: details.then_some(event.created_by_user_id),
        last_edited_by_user_id: details.then_some(event.last_edited_by_user_id),
        version: details.then_some(event.version),
        created_at: details.then_some(event.created_at),
        updated_at: details.then_some(event.updated_at),
        recurrence_rule: None,
        series_id: None,
        recurrence_id: None,
        recurrence_date: None,
        is_external: None,
        read_only: None,
    }
}

fn validate_recurrence(
    event: &EventMutation,
    recurrence_rule: &str,
) -> Result<(), EventServiceError> {
    RecurrenceRule::parse(recurrence_rule).map_err(|_| EventServiceError::InvalidInput)?;
    match &event.timing {
        EventTiming::Timed { timezone, .. } => {
            timezone
                .parse::<Tz>()
                .map_err(|_| EventServiceError::InvalidInput)?;
            Ok(())
        }
        EventTiming::AllDay { .. } => Ok(()),
    }
}

#[derive(FromRow)]
