#[derive(FromRow)]
struct AllDaySeriesRecord {
    id: i64,
    calendar_id: i64,
    title: String,
    description: Option<String>,
    location: Option<String>,
    status: String,
    all_day_start_date: String,
    all_day_end_date: String,
    created_by_user_id: i64,
